L["UFGroupHealerBuffEditorRuleInfoBarDrainColor"] = "Regeln für %s werden angezeigt. Der Geltungsbereich wird pro Regel festgelegt (Gruppe/Schlachtzug). Die Farbe folgt der ersten aktiven Regel in dieser Liste. Dauerfarben können die Farbe anhand der verbleibenden Aura-Zeit überschreiben. Die Drain-Animation folgt der ersten aktiven zeitlich begrenzten Aura in dieser Liste. Überschreibungen der Zauberfarbe gelten pro Regel (Rechtsklick zum Zurücksetzen)."
